"        protect=count>0u && float(bad)>0.12*float(count);\n"
"        if(protect) atomicAdd(rejected_tiles,1u);\n"
"        // Animated content may change drawing while sharing the camera pan.\n"
"        // Moving those original drawings rigidly does not morph their poses.\n"
"        // A region that fits substantially better with NO translation is\n"
"        // different: moving it would introduce a wobble into a stationary\n"
"        // foreground. Keep rejecting that case for the whole-frame mode.\n"
"        // A zero-flow feature alone can be a repeating cable intersection.\n"
"        // Require the surrounding region to fit the stationary image as well\n"
"        // as we require the background to fit its moving image.\n"
"        if(protect && valid && length(f.xy)<0.3 &&\n"
"           errors.y<=0.01*errors.z && errors.y<0.5*errors.x)\n"
"            atomicAdd(stationary_tiles,1u);\n"
"    }\n"
"    totals[lane]=vec4(protect ? vec3(0):errors,errors.z);\n"
"    tracks[lane].x=float(bad);\n"
"    barrier();\n"
"    for(uint step=64u;step>0u;step/=2u) {\n"
"        if(lane<step) { totals[lane]+=totals[lane+step]; tracks[lane].x+=tracks[lane+step].x; }\n"
"        barrier();\n"
"    }\n"
"    // Three source pairs of protection cover held drawings. Carry protection\n"
"    // both in screen space and along the preceding camera translation: local\n"
"    // animation need not move at the camera's speed. Store undilated history;\n"
"    // the presentation shader expands its footprint without growing it forever.\n"
"    float age=0.0;\n"
"    if(history_valid!=0) {\n"
"        ivec2 previous_tile=ivec2(floor(vec2(tile)+0.5-\n"
"            texelFetch(history,ivec2(0),0).xy*vec2(16,8)));\n"
"        previous_tile=clamp(previous_tile,ivec2(0),ivec2(15,7));\n"
"        age=max(texelFetch(history,tile+ivec2(0,1),0).r,\n"
"                texelFetch(history,previous_tile+ivec2(0,1),0).r)-1.0;\n"
"    }\n"
"    age=protect ? 3.0:max(age,0.0);\n"
"    imageStore(dst,tile+ivec2(0,1),vec4(age,0,0,0));\n"
"    if(lane==0u) {\n"
"        // Require low mean background error AND a clear improvement over\n"
"        // leaving moving images unaligned. Counting every sharp-edge residual\n"
"        // above one threshold was resolution-dependent and rejected real pans.\n"
"        float count=totals[0].z;\n"
"        float error=totals[0].x/max(count,1.0);\n"
"        float original_error=totals[0].y/max(count,1.0);\n"
"        bool background_ok=ok && count>0.0 && error<=0.01 &&\n"
"                           (length(candidate)<0.5 || error<=0.5*original_error);\n"
"        // Redrawn pixels leave residual error unrelated to camera motion, so\n"
"        // this candidate needs an improved fit, not the strict twofold gain.\n"
"        // It still needs low absolute error, majority image-area coverage and both\n"
"        // neighboring strict pairs before presentation may use it.\n"
"        bool redraw_ok=redraw_geometry && count>0.0 && error<=0.01 &&\n"
"                       count>=0.5*totals[0].w && stationary_tiles==0u &&\n"
"                       (length(candidate)<0.5 || error<original_error);\n"
"        imageStore(dst,ivec2(1,0),vec4(candidate/vec2(640,360),redraw_ok?1.0:0.0,0));\n"
"        // A thin line may cross many tiles while occupying little image area.\n"
"        // Count disagreeing pixels, not every tile touched by that line.\n"
"        bool mismatch_ok=rigid_pan!=0 ? tracks[0].x<=(12.0/128.0)*totals[0].w\n"
"                                     : rejected_tiles<=12u;\n"
"        // Sharp cable corners can outweigh a majority of coherent soft\n"
"        // background tracks. Accept that majority only when the dense fit\n"
"        // covers most of the image and improves its error at least threefold.\n"
"        bool broad_consensus=rigid_pan!=0 && geometry_ok && inlier_count>=24u &&\n"
"                             inlier_count*2u>valid_count && length(candidate)>=0.5 &&\n"
"                             count>=0.5*totals[0].w && 3.0*error<=original_error;\n"
"        ok=(strict_geometry || broad_consensus) && background_ok && mismatch_ok;\n"
"        // Limited animation no longer repeatedly disables an otherwise\n"
"        // verified camera pan. The existing background fit and coverage\n"
"        // requirements still reject large motion disagreements and cuts.\n"
"        if(rigid_pan!=0) ok=ok && stationary_tiles==0u;\n"
"        // A single well-aligned pair inside an animated shot must not turn\n"
"        // correction on for one frame. Count distinct, connected source pairs\n"
"        // on the GPU; cached presentation repeats never advance this streak.\n"
"        float previous=history_valid!=0 ? texelFetch(history,ivec2(0),0).w:0.0;\n"
"        float streak=ok ? min(previous+1.0,3.0):0.0;\n"
"        bool apply=streak>=3.0;\n"
"        vec2 motion=ok ? candidate/vec2(640,360):vec2(0);\n"
"        imageStore(dst,ivec2(0),vec4(motion,apply ? 1.0:0.0,streak));\n"
"    }\n"
"}\n";
static const char cm_weights_glsl[] =
"float lanczos(float x) {\n"
"    if(abs(x)<1e-6) return 1.0;\n"
"    if(abs(x)>=4.0) return 0.0;\n"
"    float a=3.141592653589793*x;\n"
"    return sin(a)*sin(a/4.0)/(a*a/4.0);\n"
"}\n"
"bool isolated_hold(vec4 before,vec4 held,vec4 after) {\n"
"    if(before.w<0.5 || held.w<0.5 || after.w<0.5) return false;\n"
"    vec2 a=before.xy*vec2(640,360),b=after.xy*vec2(640,360);\n"
"    float scale=min(length(a),length(b));\n"
"    return length(held.xy*vec2(640,360))<0.1 && scale>=0.5 &&\n"
"           length(a-b)<=0.25*scale;\n"
"}\n"
"vec4 confirm_redraw(vec4 flow,vec4 candidate,vec4 before,vec4 after) {\n"
"    if(flow.w>0.5 || candidate.z<0.5 || before.w<0.5 || after.w<0.5)\n"
"        return flow;\n"
"    vec2 expected=(before.xy+after.xy)*0.5;\n"
"    // Neighbors are two source intervals apart. A fixed subpixel bound would\n"
"    // reject a fast pan easing to a stop despite a small relative speed change.\n"
"    // Keep that noise floor. Source camera steps can vary by a quarter of the\n"
"    // slower verified motion while the background still fits the same pan.\n"
"    float speed=min(length(before.xy*vec2(640,360)),length(after.xy*vec2(640,360)));\n"
"    float tolerance=max(0.6,0.25*speed);\n"
"    if(0.5*length((before.xy-after.xy)*vec2(640,360))>=tolerance ||\n"
"       length((candidate.xy-expected)*vec2(640,360))>=tolerance)\n"
"        return flow;\n"
"    // Only an isolated redraw between two independently verified pan pairs.\n"
"    // A cut or a continuing stationary foreground cannot bridge this check.\n"
"    return vec4(candidate.xy,0,1);\n"
"}\n"
"vec2 camera_knot(vec4 before,vec4 after) {\n"
"    if(before.w<0.5 || after.w<0.5) return vec2(0);\n"
"    vec2 a=before.xy*vec2(640,360),b=after.xy*vec2(640,360);\n"
"    float speed=min(length(a),length(b));\n"
"    if(speed<0.5 || length(a-b)>0.5*speed) return vec2(0);\n"
"    // Smooth camera positions with [1,2,1]/4, not image pixels or animation.\n"
"    // The same knot is used on both sides of an original-frame boundary.\n"
"    // This removes source camera step jitter without guessing a different\n"
"    // velocity for just the redraw interval and snapping at its end.\n"
"    return (after.xy-before.xy)*0.25;\n"
"}\n"
"void run_weights() {\n"
"    vec4 flow=texelFetch(motion,ivec2(0),0);\n"
"    vec2 correction=vec2(0);\n"
"    bool confirmed=flow.z>0.5;\n"
"    if(rigid_pan!=0) {\n"
"        vec4 a=(available&1)!=0 ? texelFetch(earlier_motion,ivec2(0),0):vec4(0);\n"
"        vec4 b=(available&2)!=0 ? texelFetch(previous_motion,ivec2(0),0):vec4(0);\n"
"        vec4 d=(available&4)!=0 ? texelFetch(next_motion,ivec2(0),0):vec4(0);\n"
"        vec4 e=(available&8)!=0 ? texelFetch(later_motion,ivec2(0),0):vec4(0);\n"
"        vec4 previous=b,next=d,original=flow;\n"
"        if((available&3)==3)\n"
"            b=confirm_redraw(b,texelFetch(previous_motion,ivec2(1,0),0),a,original);\n"
"        if((available&6)==6)\n"
"            flow=confirm_redraw(flow,texelFetch(motion,ivec2(1,0),0),previous,next);\n"
"        if((available&12)==12)\n"
"            d=confirm_redraw(d,texelFetch(next_motion,ivec2(1,0),0),original,e);\n"
"        // Require a connected three-pair run, with at most an isolated redraw\n"
"        // confirmed from the original strict pairs on either side.\n"
"        confirmed=confirmed || (flow.w>0.5 &&\n"
"                    ((a.w>0.5 && b.w>0.5) || (b.w>0.5 && d.w>0.5) ||\n"
"                     (d.w>0.5 && e.w>0.5)));\n"
"        vec2 first=camera_knot(b,flow),last=camera_knot(flow,d);\n"
"        // Redistribute one held camera interval over its two moving neighbors.\n"
"        // Both ends of the three-interval span stay fixed. Longer camera stops\n"
"        // and direction changes are left alone; source drawings are never mixed.\n"
"        if(isolated_hold(a,b,flow)) first=(2.0*flow.xy-a.xy-b.xy)/3.0;\n"
"        if(isolated_hold(b,flow,d)) {\n"
"            first=(flow.xy+d.xy-2.0*b.xy)/3.0;\n"
"            last=(2.0*d.xy-b.xy-flow.xy)/3.0;\n"
"        }\n"
"        if(isolated_hold(flow,d,e)) last=(d.xy+e.xy-2.0*flow.xy)/3.0;\n"
"        correction=mix(first,last,fraction<0.0 ? 1.0+fraction:fraction);\n"
"        // Still pairs also have valid geometry. They cannot establish a pan\n"
"        // around one isolated drawing movement; require another moving pair.\n"
"        // A single held interval inside a pan remains supported from either end.\n"
"        bool nearby_motion=(b.w>0.5 && length(b.xy*vec2(640,360))>=0.1) ||\n"
"                           (d.w>0.5 && length(d.xy*vec2(640,360))>=0.1) ||\n"
"                           isolated_hold(a,b,flow) || isolated_hold(flow,d,e);\n"
"        confirmed=confirmed && nearby_motion;\n"
"    }\n"
"    vec2 displacement=flow.xy*image_size*fraction;\n"
"    displacement+=correction*image_size;\n"
"    // Sub-analysis-pixel noise in held shots is not useful camera motion.\n"
"    // Keep those original pixels exact instead of adding a fractional wobble.\n"
"    bool moving=rigid_pan==0 || length(flow.xy*vec2(640,360))>=0.1 ||\n"
"                length(correction*vec2(640,360))>=0.1;\n"
"    bool shifting=confirmed && moving && length(displacement)>0.02;\n"
"    if(!shifting) displacement=vec2(0);\n"
"    imageStore(dst,ivec2(0),vec4(displacement,shifting ? 1.0:0.0,0));\n"
"    imageStore(dst,ivec2(9,0),vec4(flow.xy,0,0));\n"
"    // pixel - displacement has the same fractional part across the image.\n"
"    vec2 part=fract(-displacement);\n"
"    vec2 sums=vec2(0);\n"
"    for(int i=0;i<8;i++) sums+=vec2(lanczos(part.x-float(i-3)),lanczos(part.y-float(i-3)));\n"
"    for(int i=0;i<8;i++)\n"
"        imageStore(dst,ivec2(i+1,0),vec4(lanczos(part.x-float(i-3))/sums.x,\n"
"                                       lanczos(part.y-float(i-3))/sums.y,0,0));\n"
"}\n";
static const char cm_sample_glsl[] =
"float protected_region(vec2 uv) {\n"
"    vec2 p=clamp(uv,vec2(0),vec2(1))*vec2(640,360);\n"
"    ivec2 tile=clamp(ivec2(p/vec2(40,45)),ivec2(0),ivec2(15,7));\n"
"    float distance2=400.0;\n"
"    for(int y=-1;y<=1;y++) for(int x=-1;x<=1;x++) {\n"
"        ivec2 q=tile+ivec2(x,y);\n"
"        if(any(lessThan(q,ivec2(0))) || any(greaterThan(q,ivec2(15,7)))) continue;\n"
"        if(texelFetch(motion,q+ivec2(0,1),0).r<0.5) continue;\n"
"        vec2 d=max(abs(p-(vec2(q)+0.5)*vec2(40,45))-vec2(20,22.5),vec2(0));\n"
"        distance2=min(distance2,dot(d,d));\n"
"    }\n"
"    // Preserve the protected region and a sampling margin exactly. Taper only\n"
"    // outside it, so a mask boundary cannot cut a sharp step into background\n"
"    // geometry. Resample one pose; do not blend two drawings at the boundary.\n"
"    return 1.0-smoothstep(4.0,20.0,sqrt(distance2));\n"
"}\n"
"float camera_lanczos(float x) {\n"
"    if(abs(x)<1e-6) return 1.0;\n"
"    if(abs(x)>=4.0) return 0.0;\n"
"    float a=3.141592653589793*x;\n"
"    return sin(a)*sin(a/4.0)/(a*a/4.0);\n"
"}\n"
"vec4 sample_camera() {\n"
"    ivec2 size=textureSize(base,0);\n"
"    vec2 pixel=pos*vec2(size)-0.5;\n"
"    vec4 info=texelFetch(weights,ivec2(0),0);\n"
"    if(info.z<0.5) return texelFetch(base,clamp(ivec2(round(pixel)),ivec2(0),size-1),0);\n"
"    vec2 delta=texelFetch(weights,ivec2(9,0),0).xy;\n"
"    vec2 before_pos=pos-(fraction<0.0 ? delta:vec2(0));\n"
"    // Protect both the destination and the translated sampling footprint so\n"
"    // an animated object cannot leave a shifted copy in the background.\n"
"    float protection=rigid_pan!=0 ? 0.0:\n"
"        max(protected_region(before_pos),protected_region(before_pos-info.xy/vec2(size)));\n"
"    if(protection>=1.0)\n"
"        return texelFetch(base,clamp(ivec2(round(pixel)),ivec2(0),size-1),0);\n"
"    info.xy*=1.0-protection;\n"
"    vec2 coord=pixel-info.xy;\n"
"    ivec2 origin=ivec2(floor(coord));\n"
"    if(all(greaterThanEqual(origin,ivec2(3))) && all(lessThan(origin+4,size))) {\n"
"        vec2 kernel[8],sums=vec2(0);\n"
"        for(int i=0;i<8;i++) {\n"
"            kernel[i]=protection>0.0 ? vec2(camera_lanczos(fract(coord.x)-float(i-3)),\n"
"                                           camera_lanczos(fract(coord.y)-float(i-3)))\n"
"                                     :texelFetch(weights,ivec2(i+1,0),0).xy;\n"
"            sums+=kernel[i];\n"
"        }\n"
"        vec4 color=vec4(0);\n"
"        for(int y=0;y<8;y++) {\n"
"            vec4 row=vec4(0);\n"
"            for(int x=0;x<8;x++) row+=texelFetch(base,origin+ivec2(x-3,y-3),0)*kernel[x].x/sums.x;\n"
"            color+=row*kernel[y].y/sums.y;\n"
"        }\n"
"        return color;\n"
"    }\n"
"    // A neighboring original frame supplies only the newly exposed border.\n"
"    // Interior sampling retains the selected original drawing.\n"
"    vec2 other=coord-delta*vec2(size)*(fraction<0.0 ? 1.0:-1.0);\n"
"    if(all(greaterThanEqual(other,vec2(0))) && all(lessThan(other,vec2(size))))\n"
"        return textureLod(neighbor,(other+0.5)/vec2(size),0.0);\n"
"    return texelFetch(base,clamp(ivec2(round(pixel)),ivec2(0),size-1),0);\n"
"}\n";
